<script setup lang="ts">
useHead({ title: '复盘笔记 · 持仓盯盘' })
type Entry = { liked?: boolean; likes?: number; id: string; title: string; date: string; content: string; images: string[]; comments: { id: string; text: string; date: string }[] }
const fileInput = ref<HTMLInputElement | null>(null)
const pendingDelete = ref<Entry | null>(null)
const items = ref<Entry[]>([]), selected = ref<Entry | null>(null)
const editing = ref(false), busy = ref(false), loading = ref(true), error = ref(''), comment = ref('')
const start = ref(''), end = ref(''), query = ref('')
const today = () => new Date().toLocaleDateString('sv-SE', { timeZone: 'Asia/Shanghai' })
const draft = ref({ id: '', title: '', date: today(), content: '', images: [] as string[] })
const filtered = computed(() => items.value.filter(x => (!start.value || x.date >= start.value) && (!end.value || x.date <= end.value) && (x.title + x.content).includes(query.value)))
async function load() { try { items.value = (await $fetch<{ items: Entry[] }>('/api/review-journal')).items } catch { error.value = '笔记加载失败，请检查服务后重试。' } finally { loading.value = false } }
onMounted(load)
function edit(item?: Entry) { draft.value = item ? { id: item.id, title: item.title, date: item.date, content: item.content, images: [...item.images] } : { id: '', title: '', date: today(), content: '', images: [] }; editing.value = true; error.value = '' }
async function upload(event: Event) {
 const input = event.target as HTMLInputElement
 busy.value = true; error.value = ''
 try { for (const file of Array.from(input.files || [])) {
  if (draft.value.images.length >= 9) throw Error('每篇笔记最多9张图片')
  if (!['image/png','image/jpeg','image/webp','image/gif'].includes(file.type) || file.size > 5 * 1024 * 1024) throw Error('请选择5MB以内的 PNG、JPG、WebP 或 GIF 图片')
  const data = await new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result)); reader.onerror = reject; reader.readAsDataURL(file) })
  draft.value.images.push(data)
 } } catch (e: any) { error.value = e.message || '图片读取失败' } finally { busy.value = false; input.value = '' }
}
async function submit(isComment = false) {
 busy.value = true; error.value = ''
 try {
  const item = await $fetch<Entry>('/api/review-journal', { method: 'POST', body: isComment ? { id: selected.value?.id, action: 'comment', text: comment.value } : draft.value })
  selected.value = item; editing.value = false; comment.value = ''; await load()
 } catch (e: any) { error.value = e.data?.error || '保存失败，内容已保留，请重试。' } finally { busy.value = false }
}
async function act(item: Entry, action: 'like' | 'delete') {
 if (busy.value) return
 busy.value = true; error.value = ''
 try {
  const result = await $fetch<Entry>('/api/review-journal', { method: 'POST', body: { id: item.id, action, liked: !item.liked } })
  if (action === 'delete') { items.value = items.value.filter(x => x.id !== item.id); if (selected.value?.id === item.id) selected.value = null; pendingDelete.value = null }
  else { items.value = items.value.map(x => x.id === item.id ? result : x); if (selected.value?.id === item.id) selected.value = result }
 } catch (e: any) { error.value = e.data?.error || '操作失败，请重试' } finally { busy.value = false }
}
function closeEditor() { if (window.confirm('放弃本次尚未保存的修改？')) editing.value = false }
</script>

<template>
 <main class="page-shell journal">
  <header class="hero">
   <div><span class="eyebrow">TRADING JOURNAL / 交易手记</span><h1>复盘笔记<span class="hero-dot">.</span></h1><p>记录判断，回看交易，让经验慢慢成为自己的方法。</p></div>
   <button v-if="!editing" class="primary" @click="edit()">＋ 写复盘笔记</button>
  </header>
  <p v-if="error" class="error" role="alert">{{ error }} <button v-if="!editing" @click="load">重试</button></p>
  <template v-if="!selected && !editing">
   <section class="toolbar"><div><strong>我的复盘</strong><span> {{ filtered.length }} 篇记录</span></div><label>搜索<input v-model="query" placeholder="标题、正文关键词"></label><label>开始日期<input v-model="start" type="date"></label><label>结束日期<input v-model="end" type="date" :min="start"></label><button @click="start = ''; end = ''; query = ''">重置</button></section>
   <p v-if="start && end && start > end" class="error">结束日期不能早于开始日期。</p>
   <div v-if="loading" class="empty">正在打开你的复盘笔记…</div>
   <div v-else-if="!filtered.length" class="empty"><span>✎</span><h2>{{ items.length ? '没有符合条件的笔记' : '从今天的交易，写下第一篇复盘' }}</h2><p>记录入场理由、执行过程，以及下次想做得更好的地方。</p><button class="primary" @click="edit()">开始记录</button></div>
   <div class="articles"><article v-for="item in filtered" :key="item.id" class="article"><div class="article-copy"><time>{{ item.date }} <span class="entry-tag">交易复盘</span></time><h2><button class="article-title" @click="selected = item; comment = ''">{{ item.title }}</button></h2><p class="excerpt">{{ item.content }}</p><footer><span>{{ item.images.length }} 张图片 · {{ item.comments.length }} 条评论</span><div class="row-actions"><button :class="{ liked: item.liked }" :aria-pressed="!!item.liked" :disabled="busy" @click="act(item, 'like')">{{ item.liked ? '♥ 已赞' : '♡ 点赞' }} {{ item.likes || 0 }}</button><button @click="edit(item)">编辑</button><button class="delete-link" @click="pendingDelete = item">删除</button></div></footer></div><img v-if="item.images[0]" :src="item.images[0]" alt="笔记配图"></article></div>
  </template>
  <section v-if="editing" class="paper">
   <div class="section-heading"><h2>{{ draft.id ? '编辑复盘' : '新的复盘笔记' }}</h2><button :disabled="busy" @click="closeEditor">取消</button></div>
   <form @submit.prevent="submit()"><label>复盘日期<input v-model="draft.date" type="date" required></label><label>标题<input v-model="draft.title" maxlength="120" required placeholder="用一句话，概括今天的收获" class="title-input"></label><label>正文<textarea v-model="draft.content" required maxlength="100000" rows="16" placeholder="今天的市场表现如何？\n我的交易计划与实际执行有哪些差异？\n哪些判断值得保留，哪些需要调整？" /></label>
    <div class="upload-zone"><div class="upload-icon">▧</div><div class="upload-copy"><strong>为复盘添加图片</strong><p>交易截图、行情走势，把关键时刻一起留下</p><small>{{ draft.images.length }}/9 张 · PNG / JPG / WebP / GIF · 每张最多 5MB</small></div><button type="button" class="upload-button" :disabled="busy || draft.images.length >= 9" @click="fileInput?.click()">＋ 添加图片</button><input ref="fileInput" class="file-input" type="file" accept="image/png,image/jpeg,image/webp,image/gif" multiple :disabled="busy" aria-label="上传复盘图片" @change="upload"></div>
    <div class="gallery"><figure v-for="(src, i) in draft.images" :key="i"><img :src="src" :alt="`图片 ${i + 1}`"><button type="button" :disabled="busy" @click="draft.images.splice(i, 1)">移除图片</button></figure></div>
    <div class="actions"><span>把今天的思考，留给未来的自己。</span><button class="primary" :disabled="busy">{{ busy ? '正在保存…' : draft.id ? '保存修改' : '发布笔记' }}</button></div>
   </form>
  </section>
  <article v-else-if="selected" class="paper detail">
   <div class="section-heading"><button @click="selected = null">← 全部笔记</button><div class="row-actions"><button :disabled="busy" :class="{ liked: selected.liked }" :aria-pressed="!!selected.liked" @click="act(selected, 'like')">{{ selected.liked ? '♥ 已赞' : '♡ 点赞' }} {{ selected.likes || 0 }}</button><button @click="edit(selected)">编辑笔记 ↗</button><button class="delete-link" @click="pendingDelete = selected">删除</button></div></div><time>{{ selected.date }} · 复盘笔记</time><h1>{{ selected.title }}</h1><p class="body">{{ selected.content }}</p><div class="detail-images"><a v-for="(src, i) in selected.images" :key="i" :href="src" target="_blank" rel="noopener"><img :src="src" :alt="`复盘配图 ${i + 1}`"></a></div>
   <section class="comments"><h2>留言与思考 <small>{{ selected.comments.length }}</small></h2><p v-if="!selected.comments.length" class="muted">回看时的新想法，也值得留下。</p><div v-for="c in selected.comments" :key="c.id" class="comment"><time>{{ new Date(c.date).toLocaleString('zh-CN') }}</time><p>{{ c.text }}</p></div><form @submit.prevent="submit(true)"><label>添加留言<textarea v-model="comment" required maxlength="2000" rows="3" placeholder="写下新的观察或补充…" /></label><button class="primary" :disabled="busy || !comment.trim()">{{ busy ? '提交中…' : '发布评论' }}</button></form></section>
  </article>
  <div v-if="pendingDelete" class="modal-backdrop" @keydown.esc="!busy && (pendingDelete = null)"><section class="delete-dialog" role="alertdialog" aria-modal="true" aria-labelledby="delete-title"><span class="delete-symbol">!</span><h2 id="delete-title">删除这篇复盘笔记？</h2><p>「{{ pendingDelete.title }}」将从文章列表移除，相关图片和评论也将不再显示。</p><div class="row-actions"><button autofocus :disabled="busy" @click="pendingDelete = null">保留笔记</button><button class="danger-button" :disabled="busy" @click="act(pendingDelete, 'delete')">{{ busy ? '删除中…' : '确认删除' }}</button></div><p v-if="error" role="alert" class="error">{{ error }}</p></section></div>
 </main>
</template>

<style scoped>
.journal{width:100%;max-width:1600px;padding-bottom:80px}.hero{margin:28px 0;padding:42px;border:1px solid var(--ui-hairline);border-radius:24px;background:linear-gradient(120deg,rgba(20,184,166,.14),rgba(99,102,241,.07));display:flex;align-items:center;justify-content:space-between;gap:24px}.eyebrow{font-size:11px;letter-spacing:.18em;color:#14b8a6}.hero h1{font-size:36px;line-height:1.45;font-weight:700;margin:14px 0}.hero p,.muted,small,.toolbar span{opacity:.6;font-size:13px}.primary{background:#0f766e;color:white;border-radius:10px;padding:12px 22px;font-weight:600;white-space:nowrap}button:disabled{opacity:.5;cursor:wait}.toolbar{display:flex;flex-wrap:wrap;align-items:end;gap:16px;padding:20px 0;margin-bottom:14px}.toolbar>div{margin-right:auto}.toolbar label{font-size:11px}input,textarea{display:block;width:100%;background:rgba(128,128,128,.05);border:1px solid rgba(128,128,128,.25);border-radius:9px;padding:10px 12px;color:inherit;margin-top:7px}input:focus,textarea:focus{outline:2px solid #14b8a6;outline-offset:2px}.articles{display:grid;gap:16px}.article{display:flex;text-align:left;gap:26px;width:100%;padding:28px;border:1px solid rgba(128,128,128,.2);border-radius:16px;transition:transform .2s,background .2s}.article:hover{transform:translateY(-2px);background:rgba(20,184,166,.05)}.article-copy{flex:1;min-width:0}time{font-size:12px;color:#14b8a6}.article h2{font-size:22px;font-weight:600;margin:10px 0}.article p{opacity:.65;line-height:1.8;overflow-wrap:anywhere}.article footer{margin-top:24px;font-size:12px;opacity:.65}.article footer span{float:right}.article>img{width:170px;height:140px;object-fit:cover;border-radius:10px}.paper{width:100%;max-width:none;margin:24px auto;border:1px solid rgba(128,128,128,.2);border-radius:20px;padding:36px}.section-heading{display:flex;justify-content:space-between;align-items:center;margin-bottom:22px;gap:16px}.section-heading h2,.comments h2{font-size:20px;font-weight:600}form>label{display:block;margin-bottom:22px;font-size:13px}.title-input{font-size:22px}textarea{line-height:1.9;resize:vertical}.upload{cursor:pointer;color:#14b8a6}.upload input{font-size:12px}.gallery{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.gallery img{width:100%;height:140px;object-fit:cover;border-radius:10px}.gallery button{font-size:12px;margin-top:8px}.actions{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-top:30px}.actions span{font-size:12px;opacity:.5}.detail h1{font-size:32px;font-weight:700;margin:18px 0 30px;overflow-wrap:anywhere}.body,.comment p{white-space:pre-wrap;overflow-wrap:anywhere;line-height:2}.detail-images{display:grid;gap:18px;margin-top:24px}.detail-images img{max-width:100%;border-radius:12px}.comments{margin-top:40px;padding-top:26px;border-top:1px solid rgba(128,128,128,.2)}.comments form{margin-top:24px}.comment{padding:18px 0;border-bottom:1px solid rgba(128,128,128,.1)}.empty{text-align:center;padding:70px 20px;border:1px dashed rgba(128,128,128,.3);border-radius:20px}.empty>span{font-size:40px;color:#14b8a6}.empty h2{font-size:22px;margin:16px}.empty p{opacity:.6;margin-bottom:24px}.error{padding:14px;border-radius:9px;background:rgba(239,68,68,.12);color:#ef7777}@media(max-width:640px){.hero{padding:24px;align-items:start;flex-direction:column}.hero h1{font-size:28px}.paper{padding:20px}.article{padding:20px}.article>img{width:80px;height:90px}.toolbar label{flex:1;min-width:130px}.gallery{grid-template-columns:repeat(2,1fr)}.actions span{display:none}}

.journal{padding-left:clamp(20px,4vw,64px);padding-right:clamp(20px,4vw,64px)}.hero{padding:32px 40px;margin-top:24px}.hero h1{font-size:40px;letter-spacing:.02em;margin:8px 0}.hero-dot{color:#14b8a6}.toolbar{padding:22px 26px;border:1px solid rgba(128,128,128,.18);border-radius:16px;background:rgba(128,128,128,.025)}.toolbar strong{font-size:20px}.articles{gap:0;border:1px solid rgba(128,128,128,.18);border-radius:18px;overflow:hidden}.articles:empty{display:none}.article{padding:30px 34px;border:0;border-bottom:1px solid rgba(128,128,128,.16);border-radius:0;align-items:center}.article:last-child{border-bottom:0}.article:hover{transform:none}.article-title{text-align:left;line-height:1.5;overflow-wrap:anywhere}.article-title:hover{color:#14b8a6}.article-title:focus-visible{outline:2px solid #14b8a6;outline-offset:5px;border-radius:4px}.excerpt{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;white-space:pre-line;max-width:1050px}.entry-tag{display:inline-block;margin-left:12px;color:inherit;background:rgba(20,184,166,.08);border-radius:5px;padding:3px 8px;font-size:11px}.article footer{display:flex;justify-content:space-between;align-items:center;opacity:1;color:var(--ui-text-2);gap:16px}.article footer span{float:none;opacity:.6}.row-actions{display:flex;align-items:center;gap:22px;flex-wrap:wrap}.row-actions button{font-size:13px}.row-actions button:hover{color:#14b8a6}.row-actions .liked{color:#f47296}.row-actions .delete-link{opacity:.6}.row-actions .delete-link:hover{color:#ef7777;opacity:1}.paper{padding:36px 44px;background:rgba(128,128,128,.025)}.paper form>label:first-child input[type=date]{max-width:240px}.upload-zone{display:flex;align-items:center;gap:20px;padding:26px;border:1px dashed rgba(20,184,166,.4);border-radius:14px;background:rgba(20,184,166,.035);margin:28px 0}.upload-icon{font-size:30px;color:#14b8a6;background:rgba(20,184,166,.1);width:58px;height:58px;border-radius:14px;display:grid;place-items:center}.upload-copy{flex:1}.upload-copy strong{font-size:15px}.upload-copy p{font-size:13px;opacity:.6;margin:5px 0}.upload-button{border:1px solid rgba(20,184,166,.45);color:#14b8a6;border-radius:9px;padding:11px 18px;font-size:14px}.upload-button:hover{background:rgba(20,184,166,.1)}.file-input{display:none!important}.gallery{grid-template-columns:repeat(auto-fill,minmax(180px,1fr))}.detail .body{font-size:17px;line-height:2.1}.detail-images{grid-template-columns:repeat(auto-fit,minmax(280px,1fr));}.detail-images img{max-height:700px;object-fit:contain}.modal-backdrop{position:fixed;inset:0;background:rgba(0,0,0,.6);backdrop-filter:blur(5px);display:grid;place-items:center;z-index:100;padding:24px}.delete-dialog{width:min(480px,100%);padding:32px;border-radius:20px;background:var(--ui-surface,#182329);border:1px solid rgba(128,128,128,.3);box-shadow:0 24px 80px #0005}.delete-symbol{display:grid;place-items:center;width:44px;height:44px;border-radius:12px;background:#ef777720;color:#ef7777;font-size:24px}.delete-dialog h2{font-size:22px;margin:18px 0 12px}.delete-dialog p{font-size:14px;line-height:1.8;opacity:.7;overflow-wrap:anywhere}.delete-dialog .row-actions{justify-content:flex-end;margin-top:24px}.danger-button{background:#b8424c;color:white;border-radius:9px;padding:10px 16px}.delete-dialog .danger-button:hover{color:white;background:#a3333c}@media(max-width:700px){.journal{padding-left:16px;padding-right:16px}.hero{padding:24px}.hero h1{font-size:32px}.paper{padding:22px}.article{padding:22px;gap:16px}.article footer{align-items:start;flex-direction:column;gap:16px}.upload-zone{flex-wrap:wrap;padding:20px}.upload-icon{display:none}.upload-copy{flex-basis:100%}.upload-button{width:100%}.toolbar{padding:18px}.section-heading{flex-wrap:wrap}.row-actions{gap:16px}}
</style>
